import { Ajv } from "ajv";
import standaloneCode from "ajv/dist/standalone/index.js";
import { z } from "zod";
import { stallionObject } from "./model";

export const jsonSchema = (): Record<string, unknown> =>
  z.toJSONSchema(stallionObject, { target: "draft-07" });

export const validatorSource = (): string => {
  const ajv = new Ajv({ code: { source: true, esm: true }, unicode: false });
  const validate = ajv.compile(jsonSchema());
  return `${standaloneCode(ajv, validate)}\n`;
};

export const validatorTypes = (): string =>
  [
    'import type { ErrorObject } from "ajv";',
    'import type { StallionObject } from "../src/model";',
    "",
    "type Validate = ((data: unknown) => data is StallionObject) & { errors?: ErrorObject[] | null };",
    "",
    "export declare const validate: Validate;",
    "export default validate;",
    "",
  ].join("\n");
import { Encoder } from "cbor-x";
import { validate } from "../generated/validate.js";
import type { StallionObject } from "./model";

export type DecodeResult = { ok: true; value: StallionObject } | { ok: false; error: string };

const cbor = new Encoder({ useRecords: false, mapsAsObjects: true, variableMapSize: true });

const describeErrors = (): string =>
  (validate.errors ?? []).map((e) => `${e.instancePath || "/"} ${e.message ?? ""}`).join("; ");

export const encode = (object: StallionObject): Uint8Array => {
  if (!validate(object)) {
    throw new TypeError(`Cannot encode an invalid object: ${describeErrors()}`);
  }
  return cbor.encode(object);
};

export const decode = (bytes: Uint8Array): DecodeResult => {
  const value: unknown = cbor.decode(bytes);
  if (!validate(value)) {
    return { ok: false, error: describeErrors() };
  }
  return { ok: true, value };
};

