export { type DecodeResult, decode, encode } from "./codec";
export * from "./frame";
export * from "./ink";
export * from "./model";
import { z } from "zod";
import { colour, nativeZoom, objectId, pencilSize, point } from "./model";

export const MAX_INK_POINTS = 4096;

export const inkFrame = z.strictObject({
  strokeId: objectId,
